const base = 'https://api.openai.com/v1';
const headers = { Authorization: `Bearer ${$env.OPENAI_KEY}`, 'OpenAI-Beta': 'assistants=v2' };
const assistant = await fetch(base + '/assistants', { headers });
const thread = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/threads', headers });
const hits = await this.helpers.httpRequest({ url: 'https://api.example.com/v1/search?q=x' });
return [{ json: { thread, hits } }];

const answer = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.openai.com/v1/responses', body: $json });
const clip = await this.helpers.httpRequest({ url: 'https://api.vendor.io/v1/videos/42' });
return [{ json: { answer, clip } }];
